import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import {fileURLToPath} from 'node:url';
import {registerHooks} from 'node:module';
import {tmpdir} from 'node:os';
const root=fs.realpathSync(path.dirname(fileURLToPath(import.meta.url)));
const cache=fs.realpathSync(process.env.PF_JITI_CACHE_DIR);
const relative=path.relative(root,cache);
assert.ok(relative&&!relative.startsWith('..')&&!path.isAbsolute(relative));
assert.equal(fs.realpathSync(tmpdir()),root);
const staticUrl=import.meta.resolve('jiti/static'),plainUrl=import.meta.resolve('jiti');
const babelUrl=new URL('../dist/babel.cjs',staticUrl).href;
const key=Symbol.for('super-pi.pf02-bundled-cache-adapter');
const counts=globalThis[key]={staticLoads:0,plainLoads:0,babelLoads:0,factories:0,loaderLoads:0,loadCreateJitiMs:0};
const loaderUrl=new URL('../../packages/coding-agent/dist/core/extensions/loader.js',import.meta.url).href;
const original=fs.readFileSync(path.join(root,'loader-original.js'),'utf8');
const importNeedle='createJitiPromise ??= import("jiti/static").then((module) => module.createJiti);';
assert.equal(original.split(importNeedle).length,2);
const candidate=original.replace(importNeedle,'createJitiPromise ??= (isBunBinary ? import("jiti/static") : import("jiti")).then((module) => module.createJiti);');
const waitNeedle='const createJiti = await loadCreateJiti();';
assert.equal(original.split(waitNeedle).length,2);
registerHooks({load(url,context,nextLoad){
  if(url===babelUrl)counts.babelLoads++;
  const result=nextLoad(url,context);
  if(url===loaderUrl){
    counts.loaderLoads++;
    const chosen=process.env.PF_ARM==='candidate'?candidate:original;
    const source=chosen.replace(waitNeedle,"const pfCounts = globalThis[Symbol.for('super-pi.pf02-bundled-cache-adapter')]; const pfFirst = pfCounts.factories === 0; const pfStart = performance.now(); "+waitNeedle+" if (pfFirst) pfCounts.loadCreateJitiMs = performance.now() - pfStart;");
    return {...result,source};
  }
  if(url!==staticUrl&&url!==plainUrl)return result;
  if(url===staticUrl)counts.staticLoads++;else counts.plainLoads++;
  const text=typeof result.source==='string'?result.source:Buffer.from(result.source).toString('utf8');
  const needle='return _createJiti(id, opts, {';
  assert.equal(text.split(needle).length,2,'Jiti factory shape changed');
  // Same directory-only adapter in both arms; leave moduleCache and transform behavior intact.
  const source=text.replace(needle,"opts.fsCache = process.env.PF_JITI_CACHE_DIR;\n  globalThis[Symbol.for('super-pi.pf02-bundled-cache-adapter')].factories++;\n  "+needle);
  return {...result,source};
}});
process.on('exit',function receipt(code){fs.writeFileSync(path.join(root,`cache-receipt-${process.pid}.json`),JSON.stringify({pid:process.pid,code,closed:new Date().toISOString(),tmpdir:tmpdir(),cache,...counts}));});

