/**
 * Extension loader - loads TypeScript extension modules using jiti.
 *
 */

import * as fs from "node:fs";
import { createRequire } from "node:module";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import type { Provider } from "@super-pi/ai";
import { createOpenAICodexTransportOwner } from "@super-pi/ai/api/openai-codex-responses";
import type { KeyId } from "@super-pi/tui";
import { CONFIG_DIR_NAME, getAgentDir, isBunBinary } from "../../config.ts";
import { resolvePath } from "../../utils/paths.ts";
import { createEventBus, type EventBus } from "../event-bus.ts";
import { SessionExecutionBoundary } from "../execution-boundary.ts";
import type { ExecOptions } from "../exec.ts";
import { ExtensionExecOwner } from "../extension-exec-owner.ts";
import { readPiManifest } from "../pi-manifest.ts";
import { compareCanonicalIdentifiers } from "../prefix-manifest.ts";
import { createSyntheticSourceInfo } from "../source-info.ts";
import { time } from "../timings.ts";
import type {
	EntryRenderer,
	Extension,
	ExtensionAPI,
	ExtensionFactory,
	ExtensionObserverOptions,
	ExtensionRuntime,
	CompactionStrategy,
	LoadExtensionsResult,
	MarkdownTransformer,
	MessageRenderer,
	ProviderConfig,
	RegisteredCommand,
	ToolDefinition,
	ToolRendererResolver,
} from "./types.ts";

type CreateJiti = typeof import("jiti/static")["createJiti"];
let createJitiPromise: Promise<CreateJiti> | undefined;

function loadCreateJiti(): Promise<CreateJiti> {
	createJitiPromise ??= import("jiti/static").then((module) => module.createJiti);
	return createJitiPromise;
}

const require = createRequire(import.meta.url);

const isTypeScriptSourceRuntime = !isBunBinary && path.extname(fileURLToPath(import.meta.url)) === ".ts";

/**
 * Get aliases for jiti (used in built Node.js mode).
 * In Bun binary mode, virtualModules is used instead.
 */
let _aliases: Record<string, string> | null = null;

function getAliases(): Record<string, string> {
	if (_aliases) return _aliases;

	const __dirname = path.dirname(fileURLToPath(import.meta.url));
	const packageIndex = path.resolve(__dirname, "../..", "index.js");

	const typeboxEntry = require.resolve("typebox");
	const typeboxCompileEntry = require.resolve("typebox/compile");
	const typeboxValueEntry = require.resolve("typebox/value");

	const packagesRoot = path.resolve(__dirname, "../../../../");
	const resolveWorkspaceOrImport = (workspaceRelativePath: string, specifier: string): string => {
		const workspacePath = path.join(packagesRoot, workspaceRelativePath);
		if (fs.existsSync(workspacePath)) {
			return workspacePath;
		}
		return fileURLToPath(import.meta.resolve(specifier));
	};

	const piCodingAgentEntry = packageIndex;
	const piAgentCoreEntry = resolveWorkspaceOrImport("agent/dist/index.js", "@super-pi/agent-core");
	const piTuiEntry = resolveWorkspaceOrImport("tui/dist/index.js", "@super-pi/tui");
	// Extensions resolve the pi-ai root to the compat entrypoint (a strict
	// superset of the core entrypoint): existing extensions using the old
	// global API keep working at runtime until compat is removed.
	const piAiCompatEntry = resolveWorkspaceOrImport("ai/dist/compat.js", "@super-pi/ai/compat");
	const piAiOauthEntry = resolveWorkspaceOrImport("ai/dist/oauth.js", "@super-pi/ai/oauth");
	const piAiProvidersEntry = resolveWorkspaceOrImport(
		"ai/dist/providers/all.js",
		"@super-pi/ai/providers/all",
	);

	_aliases = {
		"@super-pi/coding-agent/internal/session-lease": path.resolve(__dirname, "../session-lease"),
		"@super-pi/coding-agent/internal/files": path.resolve(__dirname, "../files"),
		"@super-pi/coding-agent/internal/tasks": path.resolve(__dirname, "../tasks"),
		"@super-pi/ai/api/openai-codex-responses": resolveWorkspaceOrImport(
			"ai/dist/api/openai-codex-responses.js", "@super-pi/ai/api/openai-codex-responses",
		),
		"@super-pi/coding-agent": piCodingAgentEntry,
		"@super-pi/agent-core": piAgentCoreEntry,
		"@super-pi/tui": piTuiEntry,
		"@super-pi/ai/providers/all": piAiProvidersEntry,
		"@super-pi/ai/compat": piAiCompatEntry,
		"@super-pi/ai/oauth": piAiOauthEntry,
		"@super-pi/ai": piAiCompatEntry,
		"@mariozechner/pi-coding-agent": piCodingAgentEntry,
		"@mariozechner/pi-agent-core": piAgentCoreEntry,
		"@mariozechner/pi-tui": piTuiEntry,
		"@mariozechner/pi-ai/providers/all": piAiProvidersEntry,
		"@mariozechner/pi-ai/compat": piAiCompatEntry,
		"@mariozechner/pi-ai/oauth": piAiOauthEntry,
		"@mariozechner/pi-ai": piAiCompatEntry,
		typebox: typeboxEntry,
		"typebox/compile": typeboxCompileEntry,
		"typebox/value": typeboxValueEntry,
		"@sinclair/typebox": typeboxEntry,
		"@sinclair/typebox/compile": typeboxCompileEntry,
		"@sinclair/typebox/value": typeboxValueEntry,
	};

	return _aliases;
}

type HandlerFn = (...args: unknown[]) => Promise<unknown> | unknown;

type PendingRuntimeChange =
	| { type: "registerProvider"; name: string; config: ProviderConfig }
	| { type: "registerNativeProvider"; provider: Provider }
	| { type: "unregisterProvider"; name: string };

let extensionCacheCwd: string | undefined;
let extensionCacheGeneration = 0;
const extensionCache = new Map<string, ExtensionFactory>();
let virtualModulesPromise: Promise<Record<string, unknown>> | undefined;

function loadVirtualModules(): Promise<Record<string, unknown>> {
	virtualModulesPromise ??= import("./virtual-modules.ts").then((module) => module.VIRTUAL_MODULES);
	return virtualModulesPromise;
}

interface ExtensionCacheToken {
	cwd: string;
	generation: number;
}

export function clearExtensionCache(): void {
	extensionCache.clear();
	extensionCacheCwd = undefined;
	extensionCacheGeneration++;
}

function useExtensionCacheCwd(cwd: string): ExtensionCacheToken {
	const resolvedCwd = resolvePath(cwd);
	if (extensionCacheCwd !== undefined && extensionCacheCwd !== resolvedCwd) {
		clearExtensionCache();
	}
	extensionCacheCwd = resolvedCwd;
	return { cwd: resolvedCwd, generation: extensionCacheGeneration };
}

function ignoreRuntimeDisposalRejection(): void {} // Awaited session shutdown/reload reports cleanup failures.

/**
 * Create a runtime with throwing stubs for action methods.
 * Runner.bindCore() replaces these with real implementations.
 */
export function createExtensionRuntime(): ExtensionRuntime {
	const notInitialized = () => {
		throw new Error("Extension runtime not initialized. Action methods cannot be called during extension loading.");
	};
	const state: { staleMessage?: string } = {};
	const eventBusUnsubscribers = new Set<() => void>();
	const assertActive = () => {
		if (state.staleMessage) {
			throw new Error(state.staleMessage);
		}
	};

	const codexOwner = createOpenAICodexTransportOwner();
	const executionBoundary = new SessionExecutionBoundary();
	const runtime: ExtensionRuntime = {
		compactionStrategies: new Map(),
		executionBoundary,
		execOwner: new ExtensionExecOwner(executionBoundary),
		codexRemoteCompactionEnabled: false,
		openAIResponsesDispatch: undefined,
		codexDispatch: { owner: codexOwner, assertCurrent() { assertActive(); runtime.executionBoundary.assertCurrent(); } },
		openAIResponsesOwner: undefined,
		providerOwnerDisposal: undefined,
		disposeProviderOwners: () => {
			if (runtime.providerOwnerDisposal) return runtime.providerOwnerDisposal;
			runtime.openAIResponsesDispatch = undefined;
			const owners = runtime.openAIResponsesOwner ? [codexOwner, runtime.openAIResponsesOwner] : [codexOwner];
			let revokeError: unknown;
			let revokeFailed = false;
			let deadline: ReturnType<typeof setTimeout> | undefined;
			const cleanup = Promise.resolve().then(async () => {
				const pending: Promise<void>[] = [];
				for (const owner of owners) {
					try { pending.push(Promise.resolve(owner.dispose())); } catch (error) { pending.push(Promise.reject(error)); }
				}
				const results = await Promise.allSettled(pending);
				if (revokeFailed) throw revokeError;
				for (const result of results) if (result.status === "rejected") throw result.reason;
			});
			const timeout = new Promise<never>((_resolve, reject) => {
				deadline = setTimeout(() => reject(new Error("Provider owner cleanup timed out; shutdown remains unconfirmed")), 10_000);
			});
			runtime.providerOwnerDisposal = Promise.race([cleanup, timeout]).finally(() => clearTimeout(deadline));
			// Publish the join operation before synchronous abort observers can reenter.
			for (const owner of owners) {
				try { owner.revoke(); } catch (error) { if (!revokeFailed) { revokeFailed = true; revokeError = error; } }
			}
			return runtime.providerOwnerDisposal;
		},
		sendMessage: notInitialized,
		sendUserMessage: notInitialized,
		appendEntry: notInitialized,
		setSessionName: notInitialized,
		getSessionName: notInitialized,
		setLabel: notInitialized,
		getActiveTools: notInitialized,
		getAllTools: notInitialized,
		buildProviderRequestPayload: () => Promise.reject(new Error("Extension runtime not initialized")),
		withSupplementalSummary: () => Promise.reject(new Error("Extension runtime not initialized")),
		compactProviderRequestPayload: () => Promise.reject(new Error("Extension runtime not initialized")),
		setActiveTools: notInitialized,
		// registerTool() is valid during extension load; refresh is only needed post-bind.
		refreshTools: () => {},
		getCommands: notInitialized,
		setModel: () => Promise.reject(new Error("Extension runtime not initialized")),
		getThinkingLevel: notInitialized,
		setThinkingLevel: notInitialized,
		flagValues: new Map(),
		pendingProviderRegistrations: [],
		pendingNativeProviderRegistrations: [],
		assertActive,
		invalidate: (message, ownersCleanupStarted = false) => {
			if (state.staleMessage) return;
			runtime.nativePermissions?.dispose();
			runtime.compactionStrategies.clear();
			runtime.codexRemoteCompactionEnabled = false;
			runtime.openAIResponsesDispatch = undefined;
			if (!ownersCleanupStarted) {
				void runtime.disposeProviderOwners().catch(ignoreRuntimeDisposalRejection);
				void runtime.executionBoundary.dispose().catch(ignoreRuntimeDisposalRejection);
				void runtime.nativeTasks?.dispose().catch(ignoreRuntimeDisposalRejection);
				void runtime.nativeFiles?.dispose().catch(ignoreRuntimeDisposalRejection);
			}
			state.staleMessage =
				message ??
				"This extension ctx is stale after session replacement or reload. Do not use a captured pi or command ctx after ctx.newSession(), ctx.fork(), ctx.switchSession(), or ctx.reload(). For newSession, fork, and switchSession, move post-replacement work into withSession and use the ctx passed to withSession. For reload, do not use the old ctx after await ctx.reload().";
			for (const unsubscribe of eventBusUnsubscribers) unsubscribe();
			eventBusUnsubscribers.clear();
		},
		trackEventBusSubscription: (unsubscribe) => {
			let active = true;
			const trackedUnsubscribe = () => {
				if (!active) return;
				active = false;
				eventBusUnsubscribers.delete(trackedUnsubscribe);
				unsubscribe();
			};
			eventBusUnsubscribers.add(trackedUnsubscribe);
			return trackedUnsubscribe;
		},
		// Pre-bind: queue registrations so bindCore() can flush them once the
		// model registry is available. bindCore() replaces both with direct calls.
		registerProvider: (name, config, extensionPath = "<unknown>") => {
			runtime.pendingProviderRegistrations.push({ name, config, extensionPath });
		},
		registerNativeProvider: (provider, extensionPath = "<unknown>") => {
			runtime.pendingNativeProviderRegistrations.push({ provider, extensionPath });
		},
		unregisterProvider: (name) => {
			let writeIndex = 0;
			for (const registration of runtime.pendingProviderRegistrations) {
				if (registration.name === name) continue;
				runtime.pendingProviderRegistrations[writeIndex++] = registration;
			}
			runtime.pendingProviderRegistrations.length = writeIndex;
			writeIndex = 0;
			for (const registration of runtime.pendingNativeProviderRegistrations) {
				if (registration.provider.id === name) continue;
				runtime.pendingNativeProviderRegistrations[writeIndex++] = registration;
			}
			runtime.pendingNativeProviderRegistrations.length = writeIndex;
		},
	};

	runtime.executionBoundary.register("provider:openai-codex", codexOwner);
	return runtime;
}

/**
 * Create the ExtensionAPI for an extension.
 * Registration methods write to the extension object.
 * Action methods delegate to the shared runtime.
 */
function createExtensionAPI(
	extension: Extension,
	runtime: ExtensionRuntime,
	cwd: string,
	eventBus: EventBus,
): { api: ExtensionAPI; commit: () => void; discard: () => void } {
	const finiteNonNegative = (name: string, value: number): number => {
		if (!Number.isFinite(value) || value < 0) {
			throw new RangeError(`${name} must be a finite non-negative number`);
		}
		return value;
	};
	const finitePositive = (name: string, value: number): number => {
		if (!Number.isFinite(value) || value <= 0) {
			throw new RangeError(`${name} must be a finite positive number`);
		}
		return value;
	};
	const finitePositiveInteger = (name: string, value: number): number => {
		if (!Number.isSafeInteger(value) || value <= 0) {
			throw new RangeError(`${name} must be a finite positive integer`);
		}
		return value;
	};
	const pendingFlagValues = new Map<string, boolean | string>();
	const pendingRuntimeChanges: PendingRuntimeChange[] = [];
	const loadingUnsubscribers: Array<() => void> = [];
	let state: "loading" | "active" | "failed" = "loading";
	const assertActive = () => {
		if (state === "failed") {
			throw new Error(`Extension "${extension.path}" failed to load and its API is no longer active.`);
		}
		runtime.assertActive();
	};
	const applyRuntimeChange = (change: PendingRuntimeChange) => {
		if (state === "loading") {
			pendingRuntimeChanges.push(change);
			return;
		}
		applyPendingRuntimeChange(runtime, extension.path, change);
	};
	const clearPending = () => {
		pendingFlagValues.clear();
		pendingRuntimeChanges.length = 0;
		loadingUnsubscribers.length = 0;
	};

	const api = {
		// Registration methods - write to extension
		registerCompactionStrategy(strategy: CompactionStrategy): void {
			assertActive();
			if (state !== "loading") throw new Error("Compaction strategies must be registered during extension loading");
			if (!strategy || typeof strategy.id !== "string" || !/^[a-z0-9][a-z0-9._-]{0,79}$/.test(strategy.id) || typeof strategy.prepare !== "function") {
				throw new TypeError("Invalid compaction strategy");
			}
			if (runtime.compactionStrategies.has(strategy.id)) throw new Error(`Duplicate compaction strategy: ${strategy.id}`);
			if (runtime.compactionStrategies.size >= 16) throw new Error("At most 16 compaction strategies may be registered");
			const registered = { id: strategy.id, prepare: strategy.prepare, extensionPath: extension.path };
			runtime.compactionStrategies.set(registered.id, registered);
			loadingUnsubscribers.push(() => {
				if (runtime.compactionStrategies.get(registered.id) === registered) runtime.compactionStrategies.delete(registered.id);
			});
		},
		on(event: string, handler: HandlerFn, options?: { phase: "image-processing" }): void {
			assertActive();
			if (event === "input" && options?.phase === "image-processing") event = "input:image-processing";
			const list = extension.handlers.get(event) ?? [];
			list.push(handler);
			extension.handlers.set(event, list);
		},

		observe(event: string, handler: HandlerFn, options: ExtensionObserverOptions = {}): void {
			assertActive();
			const list = extension.observers.get(event) ?? [];
			list.push({
				handler,
				slowThresholdMs: finiteNonNegative("slowThresholdMs", options.slowThresholdMs ?? 100),
				timeoutMs: finitePositive("timeoutMs", options.timeoutMs ?? 1_000),
				disableAfterErrors: finitePositiveInteger("disableAfterErrors", options.disableAfterErrors ?? 3),
				consecutiveErrors: 0,
				disabled: false,
			});
			extension.observers.set(event, list);
		},

		registerTool(tool: ToolDefinition): void {
			assertActive();
			extension.tools.set(tool.name, {
				definition: tool,
				sourceInfo: extension.sourceInfo,
			});
			runtime.refreshTools();
		},

		registerToolRenderer(resolver: ToolRendererResolver): void {
			assertActive();
			if (typeof resolver !== "function") throw new TypeError("registerToolRenderer requires a synchronous resolver function");
			const resolvers = extension.toolRenderers ??= [];
			if (resolvers.length >= 64) throw new RangeError("An extension may register at most 64 tool renderer resolvers");
			resolvers.push(resolver);
		},

