import assert from 'node:assert/strict';
import path from 'node:path';
export default function(pi){
 pi.registerCommand('pf-lifecycle-ready',{description:'Input ACK',handler:async()=>{process.stderr.write('PF_INPUT_ACK:'+JSON.stringify({activeTools:pi.getActiveTools().length,commands:pi.getCommands().length})+'\n');}});
 pi.registerCommand('pf-first-use',{description:'Offline first-use probe',handler:async()=>{
  const counts=globalThis[Symbol.for('super-pi.pf02-bundled-cache-adapter')];
  const before={...counts};const started=performance.now();
  const {createReadTool}=await import('../../packages/coding-agent/dist/core/tools/read.js');
  const readResult=await createReadTool(process.cwd()).execute('pf-read',{path:path.join(process.cwd(),'read-fixture.txt')});
  assert.ok(readResult.content.some(c=>c.type==='text'&&c.text.includes('pf-read-content')));
  const readMs=performance.now()-started,afterRead={...counts};
  const {loadExtensions}=await import('../../packages/coding-agent/dist/core/extensions/loader.js');
  const transformStart=performance.now();
  const loaded=await loadExtensions([path.join(process.cwd(),'uncached.ts')],process.cwd());
  assert.deepEqual(loaded.errors,[]);
  assert.equal(loaded.extensions[0].flags.get('uncached').default,'42');
  const transformMs=performance.now()-transformStart;
  await loaded.runtime.disposeProviderOwners();await loaded.runtime.executionBoundary.dispose();
  process.stderr.write('PF_FIRST_USE:'+JSON.stringify({readMs,transformMs,totalMs:performance.now()-started,before,afterRead,after:{...counts}})+'\n');
 }});
 pi.on('session_start',(_event,ctx)=>ctx.ui.setTitle('PF_SESSION_START'));
 pi.on('session_shutdown',()=>process.stderr.write('PF_SESSION_SHUTDOWN\n'));
}

